export interface ConnectorConfig {
  /** HubSpot OAuth access token (env: HUBSPOT_ACCESS_TOKEN) */
  hubspotAccessToken: string;
  /** HubSpot API base URL, e.g. https://api.hubapi.com */
  hubspotBaseUrl?: string;
  /** Optional pre-resolved communication ID (used when search is not implemented) */
  hubspotCommunicationId?: string;
  /** MindCloud Universal API token (env: MINDCLOUD_API_TOKEN) */
  mindcloudApiToken: string;
  /** Google Sheets spreadsheet ID */
  googleSheetsSpreadsheetId: string;
  /** Google Sheets worksheet/tab name */
  googleSheetsWorksheet: string;
  /** Injected fetch for testing */
  fetch?: typeof fetch;
}

export interface CalendlyCancelledPayload {
  event: string;
  created_at: string;
  created_by: string;
  payload: {
    uri: string;
    email: string;
    name: string;
    status: string;
    timezone: string;
    event: string;
    cancellation: {
      canceled_by: string;
      reason: string;
      canceler_type: string;
      created_at: string;
    };
    rescheduled: boolean;
  };
}

export interface HandleResult {
  hubspotCommunicationDeleted?: string;
  googleSheetsRowAppended?: {
    spreadsheetId: string;
    tableRange: string;
  };
}

function extractCommunicationId(eventUrl: string): string | null {
  const match = eventUrl.match(/\/scheduled_events\/([^\/]+)/);
  return match ? match[1] : null;
}

export async function handle(
  payload: CalendlyCancelledPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  if (payload.event !== 'invitee.canceled') {
    throw new Error(`Unsupported event type: ${payload.event}. Only 'invitee.canceled' is handled.`);
  }
  if (!payload.payload?.email) {
    throw new Error('Missing required field: payload.email');
  }
  if (!payload.payload?.cancellation?.reason) {
    throw new Error('Missing required field: payload.cancellation.reason');
  }
  const startTime = payload.payload.cancellation.created_at;
  if (!startTime) {
    throw new Error('Missing required field: payload.cancellation.created_at (used as start_time)');
  }

  const email = payload.payload.email;
  const reason = payload.payload.cancellation.reason;

  const fetchImpl = config.fetch ?? globalThis.fetch;
  if (!fetchImpl) {
    throw new Error('fetch is not available. Provide config.fetch or ensure global fetch exists.');
  }

  const result: HandleResult = {};

  // HubSpot delete engagement
  let communicationId = config.hubspotCommunicationId;
  if (!communicationId && config.hubspotBaseUrl) {
    communicationId = extractCommunicationId(payload.payload.event);
  }
  if (communicationId && config.hubspotBaseUrl && config.hubspotAccessToken) {
    const hubspotUrl = `${config.hubspotBaseUrl.replace(/\/$/, '')}/crm/v3/objects/communications/${communicationId}`;
    const hubspotResponse = await fetchImpl(hubspotUrl, {
      method: 'DELETE',
      headers: {
        Authorization: `Bearer ${config.hubspotAccessToken}`,
        'Content-Type': 'application/json',
      },
    });
    if (!hubspotResponse.ok) {
      throw new Error(`HubSpot delete failed: ${hubspotResponse.status} ${hubspotResponse.statusText} for ${hubspotUrl}`);
    }
    result.hubspotCommunicationDeleted = communicationId;
  }

  // Google Sheets append row via MindCloud
  const mindcloudUrl = 'https://connect.mindcloud.co/v2/universal/apps/googleSheets/actions/append-rows/run';
  const sheetBody = {
    arguments: {
      spreadsheetId: config.googleSheetsSpreadsheetId,
      worksheet: config.googleSheetsWorksheet,
      'values[]': [
        {
          col1: startTime,
          col2: email,
          col3: reason,
        },
      ],
    },
  };
  const sheetResponse = await fetchImpl(mindcloudUrl, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.mindcloudApiToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(sheetBody),
  });
  if (!sheetResponse.ok) {
    throw new Error(`Google Sheets append failed: ${sheetResponse.status} ${sheetResponse.statusText} for ${mindcloudUrl}`);
  }
  const sheetData = (await sheetResponse.json()) as {
    data?: Array<{ spreadsheetId: string; tableRange: string }>;
  };
  if (sheetData.data?.[0]) {
    result.googleSheetsRowAppended = {
      spreadsheetId: sheetData.data[0].spreadsheetId,
      tableRange: sheetData.data[0].tableRange,
    };
  }

  return result;
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, CalendlyCancelledPayload } from './connector';
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      hubspotAccessToken: 'test-hubspot-token',
      mindcloudApiToken: 'test-mindcloud-token',
      googleSheetsSpreadsheetId: '1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgvE2upms',
      googleSheetsWorksheet: 'Audit Log',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as CalendlyCancelledPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.googleSheetsRowAppended).toBeDefined();
  });
});

describe('handle', () => {
  it('happy path: deletes HubSpot engagement and appends to Google Sheets', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.endsWith('/crm/v3/objects/communications/evt123') && req.method === 'DELETE') {
        return jsonResponse({}, 204);
      }
      if (req.url.endsWith('/append-rows/run') && req.method === 'POST') {
        return jsonResponse({
          success: true,
          data: [
            {
              spreadsheetId: '1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgvE2upms',
              tableRange: 'Audit Log!A1:C1',
              updates: {
                spreadsheetId: '1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgvE2upms',
                updatedCells: 3,
                updatedColumns: 3,
                updatedRange: 'Audit Log!A1:C1',
                updatedRows: 1,
              },
            },
          ],
          meta: {},
        });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const config: ConnectorConfig = {
      hubspotAccessToken: 'hubspot-token',
      hubspotBaseUrl: 'https://api.hubapi.com',
      mindcloudApiToken: 'mindcloud-token',
      googleSheetsSpreadsheetId: '1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgvE2upms',
      googleSheetsWorksheet: 'Audit Log',
      fetch,
    };

    const payload: CalendlyCancelledPayload = {
      ...SOURCE_EXAMPLE,
      payload: {
        ...SOURCE_EXAMPLE.payload,
        event: 'https://api.calendly.com/scheduled_events/evt123',
      },
    } as CalendlyCancelledPayload;

    const result = await handle(payload, config);

    expect(result.hubspotCommunicationDeleted).toBe('evt123');
    expect(result.googleSheetsRowAppended).toEqual({
      spreadsheetId: '1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgvE2upms',
      tableRange: 'Audit Log!A1:C1',
    });

    const hubspotCall = calls.find((c) => c.url.includes('/communications/evt123'));
    expect(hubspotCall).toBeDefined();
    expect(hubspotCall?.method).toBe('DELETE');
    expect(hubspotCall?.headers.get('authorization')).toBe('Bearer hubspot-token');

    const sheetsCall = calls.find((c) => c.url.includes('/append-rows/run'));
    expect(sheetsCall).toBeDefined();
    expect(sheetsCall?.method).toBe('POST');
    expect(sheetsCall?.headers.get('authorization')).toBe('Bearer mindcloud-token');
    expect(sheetsCall?.json).toEqual({
      arguments: {
        spreadsheetId: '1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgvE2upms',
        worksheet: 'Audit Log',
        'values[]': [
          {
            col1: '2024-01-16T08:00:00.000000Z',
            col2: 'jane@example.com',
            col3: 'Schedule conflict',
          },
        ],
      },
    });
  });

  it('throws when payload.email is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config: ConnectorConfig = {
      hubspotAccessToken: 'token',
      mindcloudApiToken: 'token',
      googleSheetsSpreadsheetId: 'id',
      googleSheetsWorksheet: 'ws',
      fetch,
    };
    const payload = {
      ...SOURCE_EXAMPLE,
      payload: { ...SOURCE_EXAMPLE.payload, email: '' },
    } as CalendlyCancelledPayload;

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: payload.email');
  });

  it('throws when cancellation.reason is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config: ConnectorConfig = {
      hubspotAccessToken: 'token',
      mindcloudApiToken: 'token',
      googleSheetsSpreadsheetId: 'id',
      googleSheetsWorksheet: 'ws',
      fetch,
    };
    const payload = {
      ...SOURCE_EXAMPLE,
      payload: { ...SOURCE_EXAMPLE.payload, cancellation: { ...SOURCE_EXAMPLE.payload.cancellation, reason: '' } },
    } as CalendlyCancelledPayload;

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: payload.cancellation.reason');
  });

  it('throws when cancellation.created_at (start_time) is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config: ConnectorConfig = {
      hubspotAccessToken: 'token',
      mindcloudApiToken: 'token',
      googleSheetsSpreadsheetId: 'id',
      googleSheetsWorksheet: 'ws',
      fetch,
    };
    const payload = {
      ...SOURCE_EXAMPLE,
      payload: { ...SOURCE_EXAMPLE.payload, cancellation: { ...SOURCE_EXAMPLE.payload.cancellation, created_at: '' } },
    } as CalendlyCancelledPayload;

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: payload.cancellation.created_at');
  });

  it('throws on non-2xx HubSpot response', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.endsWith('/communications/evt123') && req.method === 'DELETE') {
        return jsonResponse({ error: 'Unauthorized' }, 401);
      }
      return jsonResponse({}, 200);
    });
    const config: ConnectorConfig = {
      hubspotAccessToken: 'bad-token',
      hubspotBaseUrl: 'https://api.hubapi.com',
      mindcloudApiToken: 'token',
      googleSheetsSpreadsheetId: 'id',
      googleSheetsWorksheet: 'ws',
      fetch,
    };
    const payload = {
      ...SOURCE_EXAMPLE,
      payload: { ...SOURCE_EXAMPLE.payload, event: 'https://api.calendly.com/scheduled_events/evt123' },
    } as CalendlyCancelledPayload;

    await expect(handle(payload, config)).rejects.toThrow('HubSpot delete failed: 401 Unauthorized');
    expect(calls.length).toBe(1);
  });

  it('throws on non-2xx Google Sheets response', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.endsWith('/append-rows/run') && req.method === 'POST') {
        return jsonResponse({ error: 'Forbidden' }, 403);
      }
      if (req.url.endsWith('/communications/evt123') && req.method === 'DELETE') {
        return jsonResponse({}, 204);
      }
      return jsonResponse({}, 200);
    });
    const config: ConnectorConfig = {
      hubspotAccessToken: 'token',
      hubspotBaseUrl: 'https://api.hubapi.com',
      mindcloudApiToken: 'bad-token',
      googleSheetsSpreadsheetId: 'id',
      googleSheetsWorksheet: 'ws',
      fetch,
    };
    const payload = {
      ...SOURCE_EXAMPLE,
      payload: { ...SOURCE_EXAMPLE.payload, event: 'https://api.calendly.com/scheduled_events/evt123' },
    } as CalendlyCancelledPayload;

    await expect(handle(payload, config)).rejects.toThrow('Google Sheets append failed: 403 Forbidden');
    expect(calls.length).toBe(2);
  });

  it('skips HubSpot delete when communicationId cannot be resolved', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.endsWith('/append-rows/run') && req.method === 'POST') {
        return jsonResponse({
          success: true,
          data: [{ spreadsheetId: 'id', tableRange: 'A1:C1', updates: { spreadsheetId: 'id', updatedCells: 3, updatedColumns: 3, updatedRange: 'A1:C1', updatedRows: 1 } }],
          meta: {},
        });
      }
      return jsonResponse({}, 200);
    });
    const config: ConnectorConfig = {
      hubspotAccessToken: 'token',
      // no hubspotBaseUrl, no hubspotCommunicationId
      mindcloudApiToken: 'token',
      googleSheetsSpreadsheetId: 'id',
      googleSheetsWorksheet: 'ws',
      fetch,
    };
    const payload = {
      ...SOURCE_EXAMPLE,
      payload: { ...SOURCE_EXAMPLE.payload, event: 'https://api.calendly.com/scheduled_events/evt123' },
    } as CalendlyCancelledPayload;

    const result = await handle(payload, config);
    expect(result.hubspotCommunicationDeleted).toBeUndefined();
    expect(result.googleSheetsRowAppended).toBeDefined();
    expect(calls.length).toBe(1);
    expect(calls[0].url).toContain('/append-rows/run');
  });

  it('throws on unsupported event type', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config: ConnectorConfig = {
      hubspotAccessToken: 'token',
      mindcloudApiToken: 'token',
      googleSheetsSpreadsheetId: 'id',
      googleSheetsWorksheet: 'ws',
      fetch,
    };
    const payload = { ...SOURCE_EXAMPLE, event: 'invitee.created' } as CalendlyCancelledPayload;

    await expect(handle(payload, config)).rejects.toThrow("Unsupported event type: invitee.created");
  });
});

